//! Ten Gods (十神) Analysis
//!
//! Analyzes relationships between the Day Master (日干) and other stems/branches.
//!
//! ## Ten Gods Matrix
//!
//! | Relation | Same Polarity | Opposite Polarity |
//! |---|---|---|
//! | Same Element | Friend (比肩) | Rob Wealth (劫財) |
//! | Generated by DM | Eating God (食神) | Hurting Officer (傷官) |
//! | Controlled by DM | Indirect Wealth (偏財) | Direct Wealth (正財) |
//! | Controls DM | Seven Killings (偏官) | Direct Officer (正官) |
//! | Produces DM | Indirect Resource (偏印) | Direct Resource (正印) |

use crate::core::branch::EarthlyBranch;
use crate::core::element::ElementRelation;
use crate::core::pillars::FourPillars;
use crate::core::stem::HeavenlyStem;
use serde::{Deserialize, Serialize};

/// Ten Gods (十神)
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum TenGod {
    /// Friend (比肩) - Same element, same polarity
    Bijian,
    /// Rob Wealth (劫財) - Same element, opposite polarity
    Jiecai,
    /// Eating God (食神) - Element generated by DM, same polarity
    Shishen,
    /// Hurting Officer (傷官) - Element generated by DM, opposite polarity
    Shangguan,
    /// Indirect Wealth (偏財) - Element controlled by DM, same polarity
    Piancai,
    /// Direct Wealth (正財) - Element controlled by DM, opposite polarity
    Zhengcai,
    /// Seven Killings (偏官) - Element controlling DM, same polarity
    Pianguan,
    /// Direct Officer (正官) - Element controlling DM, opposite polarity
    Zhengguan,
    /// Indirect Resource (偏印) - Element producing DM, same polarity
    Pianyin,
    /// Direct Resource (正印) - Element producing DM, opposite polarity
    Zhengyin,
}

impl TenGod {
    /// All Ten Gods array
    pub const ALL: [TenGod; 10] = [
        Self::Bijian,
        Self::Jiecai,
        Self::Shishen,
        Self::Shangguan,
        Self::Piancai,
        Self::Zhengcai,
        Self::Pianguan,
        Self::Zhengguan,
        Self::Pianyin,
        Self::Zhengyin,
    ];

    /// Hanja notation
    pub const HANJA: [&'static str; 10] = [
        "比肩", "劫財", "食神", "傷官", "偏財", "正財", "偏官", "正官", "偏印", "正印",
    ];

    /// English name notation
    pub const HANGUL: [&'static str; 10] = [
        "Friend",
        "Rob Wealth",
        "Eating God",
        "Hurting Officer",
        "Indirect Wealth",
        "Direct Wealth",
        "Seven Killings",
        "Direct Officer",
        "Indirect Resource",
        "Direct Resource",
    ];

    /// Abbreviation (2-character)
    pub const ABBREV: [&'static str; 10] =
        ["FR", "RW", "EG", "HO", "IW", "DW", "7K", "DO", "IR", "DR"];

    /// Calculate Ten God from Day Master and another stem
    pub fn from_stems(day_master: HeavenlyStem, other: HeavenlyStem) -> Self {
        let same_polarity = day_master.polarity() == other.polarity();
        let relation = day_master.element().relation_to(other.element());

        match (relation, same_polarity) {
            (ElementRelation::Same, true) => Self::Bijian,
            (ElementRelation::Same, false) => Self::Jiecai,
            (ElementRelation::Generates, true) => Self::Shishen,
            (ElementRelation::Generates, false) => Self::Shangguan,
            (ElementRelation::Controls, true) => Self::Piancai,
            (ElementRelation::Controls, false) => Self::Zhengcai,
            (ElementRelation::ControlledBy, true) => Self::Pianguan,
            (ElementRelation::ControlledBy, false) => Self::Zhengguan,
            (ElementRelation::GeneratedBy, true) => Self::Pianyin,
            (ElementRelation::GeneratedBy, false) => Self::Zhengyin,
        }
    }

    /// Calculate Ten God from Day Master and Branch's primary stem
    pub fn from_stem_and_branch(day_master: HeavenlyStem, branch: EarthlyBranch) -> Self {
        let branch_stem = branch.primary_stem();
        Self::from_stems(day_master, branch_stem)
    }

    /// Index (0-9)
    pub const fn index(self) -> usize {
        match self {
            Self::Bijian => 0,
            Self::Jiecai => 1,
            Self::Shishen => 2,
            Self::Shangguan => 3,
            Self::Piancai => 4,
            Self::Zhengcai => 5,
            Self::Pianguan => 6,
            Self::Zhengguan => 7,
            Self::Pianyin => 8,
            Self::Zhengyin => 9,
        }
    }

    /// Hanja notation
    pub const fn hanja(self) -> &'static str {
        Self::HANJA[self.index()]
    }

    /// English name notation
    pub const fn hangul(self) -> &'static str {
        Self::HANGUL[self.index()]
    }

    /// English name alias
    pub const fn english(self) -> &'static str {
        Self::HANGUL[self.index()]
    }

    /// Abbreviation
    pub const fn abbrev(self) -> &'static str {
        Self::ABBREV[self.index()]
    }

    /// Group type: Parallel, Output, Wealth, Officer, Resource
    pub const fn group(self) -> TenGodGroup {
        match self {
            Self::Bijian | Self::Jiecai => TenGodGroup::Parallel,
            Self::Shishen | Self::Shangguan => TenGodGroup::Output,
            Self::Piancai | Self::Zhengcai => TenGodGroup::Wealth,
            Self::Pianguan | Self::Zhengguan => TenGodGroup::Officer,
            Self::Pianyin | Self::Zhengyin => TenGodGroup::Resource,
        }
    }
}

/// Ten Gods 5 Family Groups
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum TenGodGroup {
    /// Parallel (比劫) - Friend, Rob Wealth
    Parallel,
    /// Output (食傷) - Eating God, Hurting Officer
    Output,
    /// Wealth (財星) - Indirect Wealth, Direct Wealth
    Wealth,
    /// Officer (官殺) - Direct Officer, Seven Killings
    Officer,
    /// Resource (印星) - Direct Resource, Indirect Resource
    Resource,
}

impl TenGodGroup {
    pub const fn name(self) -> &'static str {
        match self {
            Self::Parallel => "Parallel",
            Self::Output => "Output",
            Self::Wealth => "Wealth",
            Self::Officer => "Officer",
            Self::Resource => "Resource",
        }
    }
}

impl std::fmt::Display for TenGod {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.hangul())
    }
}

/// Four Pillars Ten Gods Analysis Result
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TenGodAnalysis {
    pub day_master: HeavenlyStem,
    pub year_stem: TenGod,
    pub month_stem: TenGod,
    pub day_stem: TenGod,
    pub hour_stem: TenGod,
    pub year_branch: TenGod,
    pub month_branch: TenGod,
    pub day_branch: TenGod,
    pub hour_branch: TenGod,
}

impl TenGodAnalysis {
    pub fn from_pillars(pillars: &FourPillars) -> Self {
        let dm = pillars.day_master();
        Self {
            day_master: dm,
            year_stem: TenGod::from_stems(dm, pillars.year.stem),
            month_stem: TenGod::from_stems(dm, pillars.month.stem),
            day_stem: TenGod::Bijian,
            hour_stem: TenGod::from_stems(dm, pillars.hour.stem),
            year_branch: TenGod::from_stem_and_branch(dm, pillars.year.branch),
            month_branch: TenGod::from_stem_and_branch(dm, pillars.month.branch),
            day_branch: TenGod::from_stem_and_branch(dm, pillars.day.branch),
            hour_branch: TenGod::from_stem_and_branch(dm, pillars.hour.branch),
        }
    }

    pub fn counts(&self) -> [(TenGod, usize); 10] {
        let mut counts = [
            (TenGod::Bijian, 0),
            (TenGod::Jiecai, 0),
            (TenGod::Shishen, 0),
            (TenGod::Shangguan, 0),
            (TenGod::Piancai, 0),
            (TenGod::Zhengcai, 0),
            (TenGod::Pianguan, 0),
            (TenGod::Zhengguan, 0),
            (TenGod::Pianyin, 0),
            (TenGod::Zhengyin, 0),
        ];

        let all = [
            self.year_stem,
            self.month_stem,
            self.hour_stem,
            self.year_branch,
            self.month_branch,
            self.day_branch,
            self.hour_branch,
        ];

        for god in all {
            counts[god.index()].1 += 1;
        }

        counts
    }

    pub fn dominant(&self) -> TenGod {
        let counts = self.counts();
        counts
            .iter()
            .max_by_key(|(_, count)| count)
            .map(|(god, _)| *god)
            .unwrap_or(TenGod::Bijian)
    }
}

impl FourPillars {
    pub fn ten_gods(&self) -> TenGodAnalysis {
        TenGodAnalysis::from_pillars(self)
    }
}

impl std::fmt::Display for TenGodAnalysis {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        writeln!(f, "┌────────┬────────┬────────┬────────┐")?;
        writeln!(f, "│  Hour  │  Day   │ Month  │  Year  │")?;
        writeln!(f, "├────────┼────────┼────────┼────────┤")?;
        writeln!(
            f,
            "│ {:^6} │ {:^6} │ {:^6} │ {:^6} │",
            self.hour_stem.hangul(),
            self.day_stem.hangul(),
            self.month_stem.hangul(),
            self.year_stem.hangul()
        )?;
        writeln!(
            f,
            "│ {:^6} │ {:^6} │ {:^6} │ {:^6} │",
            self.hour_branch.hangul(),
            self.day_branch.hangul(),
            self.month_branch.hangul(),
            self.year_branch.hangul()
        )?;
        writeln!(f, "└────────┴────────┴────────┴────────┘")?;
        writeln!(
            f,
            "Day Master: {} ({})",
            self.day_master,
            self.day_master.element()
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::pillars::{FourPillars, SajuInput};

    #[test]
    fn test_ten_god_from_stems() {
        let dm = HeavenlyStem::Geng;

        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Geng), TenGod::Bijian);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Xin), TenGod::Jiecai);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Ren), TenGod::Shishen);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Gui), TenGod::Shangguan);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Jia), TenGod::Piancai);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Yi), TenGod::Zhengcai);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Bing), TenGod::Pianguan);
        assert_eq!(
            TenGod::from_stems(dm, HeavenlyStem::Ding),
            TenGod::Zhengguan
        );
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Wu), TenGod::Pianyin);
        assert_eq!(TenGod::from_stems(dm, HeavenlyStem::Ji), TenGod::Zhengyin);
    }

    #[test]
    fn test_user_saju_ten_gods() {
        let input = SajuInput::new_solar(2004, 11, 27, 22, 0);
        let pillars = FourPillars::calculate(&input).unwrap();
        let analysis = TenGodAnalysis::from_pillars(&pillars);

        assert_eq!(analysis.day_master, HeavenlyStem::Geng);
        assert_eq!(analysis.year_stem, TenGod::Piancai);
        assert_eq!(analysis.month_stem, TenGod::Zhengcai);
        assert_eq!(analysis.hour_stem, TenGod::Zhengguan);

        println!("{}", analysis);
    }

    #[test]
    fn test_hidden_stems() {
        let stems = EarthlyBranch::Yin.hidden_stems();
        assert_eq!(stems.len(), 3);
        assert_eq!(stems[2], HeavenlyStem::Jia);
    }
}
